// przed: InvoiceService liczy VAT, renderuje PDF, wysyła mail, zapisuje
public sealed class IssueInvoiceHandler(
    IInvoiceCalculator calc, IPdfRenderer pdf, IInvoiceRepository repo, INotifier notifier)
{
    public async Task HandleAsync(Invoice inv, CancellationToken ct)
    {
        inv.ApplyTotals(calc.Calculate(inv));
        await repo.AddAsync(inv, ct);
        await notifier.SendAsync(inv.CustomerEmail, pdf.Render(inv), ct);
    }
}

public interface IFeePolicy { string Type { get; } decimal Fee(decimal amount); }

public sealed class FeeCalculator(IEnumerable<IFeePolicy> policies)
{
    private readonly Dictionary<string, IFeePolicy> _byType = policies.ToDictionary(p => p.Type);
    public decimal Fee(Payment p) => _byType[p.Type].Fee(p.Amount);
}
