public decimal Discount(Customer? c, Cart cart)
{
    if (c is null || cart.Items.Count == 0) return 0m;
    if (!c.IsLoyal) return cart.Total * 0.02m;
    return cart.Total * (c.Years >= LoyaltyYears ? 0.10m : 0.05m);
}

public sealed record DateRange
{
    public DateOnly From { get; }
    public DateOnly To { get; }
    public DateRange(DateOnly from, DateOnly to)
    {
        if (to < from) throw new ArgumentException("To must be >= From");
        (From, To) = (from, to);
    }
}
